"""Score the index warm-up on the HDD VM (stock A against W = stock plus the warm-up commits).
Reads <dir>/results.txt (the kit's RESULT and WINDOW lines) and <dir>/warmup_lines.txt (the "Index warm-up" lines of
each run's node log, prefixed with the run label). Prints medians [range] per arm, the ratio of medians W/A with an
overlap check (disjoint ranges = "no overlap"), the sync windows, the warm-up lines, the hash check, and H1-H5 as
pre-registered. "Reads after RPC" is the kit's disk_read_MB: device reads from the moment RPC answers to the top.
usage: python3 warmup_hdd_score.py <dir>"""
import os, re, statistics, sys

if len(sys.argv) != 2:
    sys.exit(__doc__)
d = sys.argv[1]
REF = "74db18cf819561696f5c124a3c5f4ecb25b9054285b16bc598c61499b408b59c"


def kv(line):
    return dict(re.findall(r"(\w+)=(\S+)", line))


runs, wins = {}, {}
for line in open(os.path.join(d, "results.txt")):
    if " RESULT " in line or line.startswith("RESULT "):
        f = kv(line)
        runs[f["label"]] = f
    elif " WINDOW " in line or line.startswith("WINDOW "):
        f = kv(line)
        wins.setdefault(f["label"], {})[f["k"]] = f
arm_of = {lab: lab.rsplit("-", 1)[1] for lab in runs}
order = sorted(runs, key=lambda l: int(re.search(r"-r(\d+)-", l).group(1)))
print("runs:", " ".join(l.split("-", 1)[1] for l in order))

med = statistics.median


def vals(arm, key, src=None, k=None):
    out = []
    for lab in order:
        if arm_of[lab] != arm:
            continue
        v = (wins[lab][k] if k else runs[lab])[key]
        out.append(float(v))
    return out


def show(key, k=None, unit=""):
    a, w = vals("A", key, k=k), vals("W", key, k=k)
    disjoint = max(w) < min(a) or min(w) > max(a)
    name = f"{key} (window {k})" if k else key
    print(f"{name:34} A {med(a):g} [{min(a):g}-{max(a):g}]   W {med(w):g} [{min(w):g}-{max(w):g}]   "
          f"W/A {med(w) / med(a):.3f} ({(med(w) / med(a) - 1) * 100:+.1f}%, {'no overlap' if disjoint else 'overlap'})"
          f"   W-A {med(w) - med(a):+.2f}{unit}")
    return med(a), med(w), a, w


print("\n== per run (medians of 4 per arm)")
l2t = show("launch_to_top_s", unit=" s")
l2r = show("launch_to_rpc_s", unit=" s")
show("wall_s", unit=" s")
show("steady_blocks_per_s")
show("cpu_s", unit=" s")
rd = show("disk_read_MB", unit=" MB")
show("read_MB_launch", unit=" MB")
show("rss_anon_max_MB", unit=" MB")
show("resident_MB_end", unit=" MB")
print("\n== sync windows (k=1: 3,106,401-3,106,600; k=2: 3,106,600-3,106,800)")
for k in ("1", "2"):
    show("blocks_per_s", k=k)
    show("read_kB_per_block", k=k)

print("\n== warm-up lines (node log)")
wl = {}
for line in open(os.path.join(d, "warmup_lines.txt")):
    if line.startswith("AI DISCLAIMER") or not line.strip():
        continue
    lab, rest = line.split(" ", 1)
    wl.setdefault(lab, []).append(rest.strip())
ends = {}
for lab in order:
    lines = wl.get(lab, [])
    m = [re.search(r"(\d+) pages \((\d+) MB\), in ([\d.]+) s", x) for x in lines]
    m = [x for x in m if x]
    if m:
        ends[lab] = (int(m[0].group(2)), float(m[0].group(3)))
    print(f"{lab}: {len(lines)} lines" + (f"; read {m[0].group(2)} MB in {m[0].group(3)} s" if m else ""))

print("\n== hash at 3,106,800")
bad = [l for l in order if runs[l].get("hash_at_3106800") != REF or runs[l].get("outcome") != "ok"]
print(f"all {len(order)} runs ok with {REF[:8]}…" if not bad else f"MISMATCH or not ok: {bad}")

print("\n== predictions")
a, w, aa, ww = l2t
r = w / a
disj = max(ww) < min(aa)
print(f"H1 {'met' if 0.35 <= r <= 0.55 and disj else 'NOT met'}: launch to top W/A {r:.3f}, "
      f"{'disjoint' if disj else 'overlapping'} ranges (bar 0.35-0.55, disjoint)")
a, w, _, _ = l2r
print(f"H2 {'met' if w <= a + 5 else 'NOT met'}: launch to RPC W {w:g} s against A {a:g} s, {w - a:+.2f} s (bar at most +5 s)")
wlabs = [l for l in order if arm_of[l] == "W"]
alabs = [l for l in order if arm_of[l] == "A"]
h3 = (all(len([x for x in wl.get(l, []) if " MB), in " in x]) == 1 and l in ends
          and 780 <= ends[l][0] <= 880 and ends[l][1] <= 120 for l in wlabs)
      and all(not wl.get(l) for l in alabs))
print(f"H3 {'met' if h3 else 'NOT met'}: every W run one end line, "
      f"{', '.join(f'{ends[l][0]} MB in {ends[l][1]:g} s' for l in wlabs if l in ends)}; "
      f"A runs with warm-up lines: {sum(1 for l in alabs if wl.get(l))} (bar 780-880 MB in at most 120 s; none in A)")
a, w, _, _ = rd
